cat << 'EOF' > check_columns.py
import pandas as pd
import os

data_dir = 'data/'
for f in os.listdir(data_dir):
    if f.endswith('.csv'):
        try:
            df = pd.read_csv(os.path.join(data_dir, f))
            cols = [c.lower().replace(' ', '_') for c in df.columns]
            if 'investment_potential_score' in cols:
                print(f"MATCH: Found 'investment potential score' in {f}")
            elif any('potential' in c for c in cols):
                print(f"PARTIAL: Found potential in {f}. Columns: {df.columns.tolist()}")
        except Exception as e:
            print(f"Error reading {f}: {e}")
EOF
python3 check_columns.py
rm check_columns.py
